func TestSupplierForwardMigrationFreshRepeatAndConstraints(t *testing.T) {
	db := openUnmigratedSupplierDatabase(t)
	runner := configuredSupplierMigrationRunner(t, db)
	if err := runner.MigrateContext(context.Background()); err != nil {
		t.Fatalf("fresh migration error = %v", err)
	}
	assertSupplierSchemaReady(t, db)
	if err := runner.MigrateContext(context.Background()); err != nil {
		t.Fatalf("repeat migration error = %v", err)
	}
	var versions int64
	if err := db.Model(new(migrationmodels.Migration)).Where("version = ?", SupplierMigrationID.String()).Count(&versions).Error; err != nil {
		t.Fatalf("count migration versions: %v", err)
	}
	if versions != 1 {
		t.Fatalf("migration version rows = %d, want 1", versions)
	}
	invalidCreditLevel := &Supplier{
		Code:         "VALUE_01",
		Name:         "VALUE_01",
		Country:      "VALUE_01",
		ContactName:  "VALUE_01",
		ContactEmail: "supplier@example.test",
		CreditLevel:  "outside-contract",
		Enabled:      true,
	}
	if err := db.Create(invalidCreditLevel).Error; err == nil {
		t.Fatal("database enum constraint accepted an undeclared value")
	}
}

