func driftSupplierSQLiteColumnType(ddl string) (string, bool) {
	for _, column := range supplierMigrationColumns[4:] {
		var declaredType string
		if column.length > 0 {
			declaredType = fmt.Sprintf("VARCHAR(%d)", column.length)
		} else {
			declaredType = "BOOLEAN"
		}
		original := fmt.Sprintf("%q %s", column.name, declaredType)
		replacement := fmt.Sprintf("%q BLOB", column.name)
		if drifted := strings.Replace(ddl, original, replacement, 1); drifted != ddl {
			return drifted, true
		}
	}
	return ddl, false
}

func driftSupplierSQLiteRequiredColumnNullable(ddl, column string) (string, bool) {
	token := fmt.Sprintf("%q", column)
	for _, line := range strings.SplitAfter(ddl, "\n") {
		if !strings.Contains(line, token) || !strings.Contains(line, " NOT NULL") {
			continue
		}
		driftedLine := strings.Replace(line, " NOT NULL", "", 1)
		return strings.Replace(ddl, line, driftedLine, 1), true
	}
	return ddl, false
}

